 * @param {DeterminismHardeningPass13Input} input
 * @returns {DeterminismHardeningPass13Result}
 */
export function evaluateDeterminismHardeningPass13(input) {
	const findings = [];
	if (!input || typeof input.id !== "string" || input.id.length === 0) {
		return { subjectId: "unknown", status: "blocked", findings: [{ code: "determinism-hardening-pass-13/missing-id", severity: "critical", evidence: ["input.id is required"] }] };
	}
	if (!Number.isFinite(input.quantity) || input.quantity < 0) {
		findings.push({ code: "determinism-hardening-pass-13/quantity-range", severity: "critical", evidence: [`quantity ${input.quantity} is outside [0, ∞)`] });
	}
	if (!/^\d{4}-\d{2}-\d{2}T/.test(input.occurredAt ?? "")) {
		findings.push({ code: "determinism-hardening-pass-13/timestamp-shape", severity: "warning", evidence: [`occurredAt ${String(input.occurredAt)} is not ISO-8601`] });
	}
	const blocked = findings.some((finding) => finding.severity === "critical");
	if (findings.length === 0) {
		findings.push({ code: "determinism-hardening-pass-13/clean", severity: "info", evidence: ["all deterministic checks passed"] });
	}
	return { subjectId: input.id, status: blocked ? "blocked" : "accepted", findings };
}

